using Microsoft.Data.Sqlite; using Workbench.Core.Workers; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed class TaskGrantRepository(WorkbenchDatabase database){readonly WorkbenchDatabase _d=database;public async Task AddAsync(Guid project,Guid id,TaskGrant grant,string grantedBy,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO task_grants(id,task_id,capability,scope,expiry,granted_by,created_at) SELECT $i,$t,$c,$s,$e,$b,$a WHERE EXISTS(SELECT 1 FROM tasks WHERE id=$t AND project_id=$p)";q.Parameters.AddWithValue("$i",id.ToString());q.Parameters.AddWithValue("$p",project.ToString());q.Parameters.AddWithValue("$t",grant.TaskId.ToString());q.Parameters.AddWithValue("$c",grant.Capability);q.Parameters.AddWithValue("$s",grant.Scope);q.Parameters.AddWithValue("$e",grant.Expiry.ToString("O"));q.Parameters.AddWithValue("$b",grantedBy);q.Parameters.AddWithValue("$a",DateTimeOffset.UtcNow.ToString("O"));await q.ExecuteNonQueryAsync(ct);}public async Task<bool> HasActiveGrantAsync(Guid project,Guid task,string capability,string scope,DateTimeOffset now,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="SELECT EXISTS(SELECT 1 FROM task_grants g JOIN tasks t ON t.id=g.task_id WHERE g.task_id=$t AND t.project_id=$p AND g.capability=$c AND g.scope=$s AND g.expiry>$e)";q.Parameters.AddWithValue("$p",project.ToString());q.Parameters.AddWithValue("$t",task.ToString());q.Parameters.AddWithValue("$c",capability);q.Parameters.AddWithValue("$s",scope);q.Parameters.AddWithValue("$e",now.ToString("O"));return Convert.ToInt64(await q.ExecuteScalarAsync(ct))==1;}}
